-- FoodRescue: PostgreSQL relational schema, 33 tables.

-- Creates tables, constraints and indexes; backend transactions remain required.

-- Run against a new empty database/schema. Integer surrogate keys use GENERATED BY DEFAULT AS IDENTITY.



CREATE TABLE quyen (
    ma varchar(40) NOT NULL,
    ten varchar(120) NOT NULL,
    PRIMARY KEY (ma)
);

COMMENT ON TABLE quyen IS 'Quyền truy cập';

CREATE TABLE quyen_phan_cong (
    phan_cong_id int NOT NULL,
    quyen_ma varchar(40) NOT NULL,
    PRIMARY KEY (phan_cong_id, quyen_ma)
);

COMMENT ON TABLE quyen_phan_cong IS 'Phân quyền nhân viên';

CREATE TABLE phan_cong_nhan_vien (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tai_khoan_id int NOT NULL,
    cua_hang_id int NOT NULL,
    bat_dau_luc timestamptz NOT NULL,
    ket_thuc_luc timestamptz,
    trang_thai varchar(24) NOT NULL,
    PRIMARY KEY (id),
    CHECK (ket_thuc_luc IS NULL OR ket_thuc_luc >= bat_dau_luc),
    CHECK (trang_thai IN ('DANG_HIEU_LUC','DA_THU_HOI'))
);

COMMENT ON TABLE phan_cong_nhan_vien IS 'Phân công nhân viên';

CREATE TABLE tai_khoan (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    email varchar(254) NOT NULL,
    mat_khau_hash text NOT NULL,
    ho_ten varchar(120) NOT NULL,
    so_dien_thoai varchar(20),
    vai_tro varchar(24) NOT NULL,
    trang_thai varchar(24) NOT NULL,
    tao_luc timestamptz NOT NULL,
    PRIMARY KEY (id),
    CHECK (vai_tro IN ('KHACH_HANG','CHU_CUA_HANG','NHAN_VIEN','QUAN_TRI_VIEN')),
    CHECK (trang_thai IN ('CHO_XAC_THUC','HOAT_DONG','BI_KHOA'))
);

COMMENT ON TABLE tai_khoan IS 'Tài khoản';

CREATE TABLE phien_dang_nhap (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tai_khoan_id int NOT NULL,
    refresh_token_hash varchar(128) NOT NULL,
    tao_luc timestamptz NOT NULL,
    het_han_luc timestamptz NOT NULL,
    thu_hoi_luc timestamptz,
    PRIMARY KEY (id),
    UNIQUE (refresh_token_hash),
    CHECK (het_han_luc > tao_luc),
    CHECK (thu_hoi_luc IS NULL OR thu_hoi_luc >= tao_luc)
);

COMMENT ON TABLE phien_dang_nhap IS 'Phiên đăng nhập';

CREATE TABLE nhat_ky_thay_doi (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nguoi_thuc_hien_id int,
    cua_hang_id int,
    loai_doi_tuong varchar(60) NOT NULL,
    ma_doi_tuong varchar(64) NOT NULL,
    hanh_dong varchar(80) NOT NULL,
    du_lieu_truoc text,
    du_lieu_sau text,
    ly_do text,
    ghi_luc timestamptz NOT NULL,
    PRIMARY KEY (id)
);

COMMENT ON TABLE nhat_ky_thay_doi IS 'Nhật ký thay đổi';

CREATE TABLE gio_mo_cua (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cua_hang_id int NOT NULL,
    thu int NOT NULL,
    gio_mo time NOT NULL,
    gio_dong time NOT NULL,
    qua_ngay bool NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (cua_hang_id, thu, gio_mo),
    CHECK (thu BETWEEN 1 AND 7),
    CHECK ((NOT qua_ngay AND gio_dong > gio_mo) OR (qua_ngay AND gio_dong <= gio_mo))
);

COMMENT ON TABLE gio_mo_cua IS 'Giờ mở cửa';

CREATE TABLE ho_so_doi_tac (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cua_hang_id int NOT NULL,
    ten_phap_ly varchar(200) NOT NULL,
    ma_dang_ky varchar(60),
    gui_luc timestamptz NOT NULL,
    ket_qua varchar(24) NOT NULL,
    ly_do text,
    nguoi_duyet_id int,
    duyet_luc timestamptz,
    PRIMARY KEY (id),
    UNIQUE (cua_hang_id),
    CHECK (ket_qua IN ('CHO_DUYET','CAN_BO_SUNG','CHAP_THUAN','TU_CHOI')),
    CHECK (ket_qua NOT IN ('CHAP_THUAN','TU_CHOI') OR (nguoi_duyet_id IS NOT NULL AND duyet_luc IS NOT NULL))
);

COMMENT ON TABLE ho_so_doi_tac IS 'Hồ sơ đối tác';

CREATE TABLE cua_hang (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    chu_so_huu_id int NOT NULL,
    ten varchar(200) NOT NULL,
    dia_chi text NOT NULL,
    vi_do numeric(9,6) NOT NULL,
    kinh_do numeric(9,6) NOT NULL,
    trang_thai varchar(24) NOT NULL,
    da_duoc_duyet bool NOT NULL,
    tao_luc timestamptz NOT NULL,
    PRIMARY KEY (id),
    CHECK (vi_do BETWEEN -90 AND 90),
    CHECK (kinh_do BETWEEN -180 AND 180),
    CHECK (trang_thai IN ('CHO_DUYET','HOAT_DONG','TAM_NGUNG','BI_KHOA','TU_CHOI'))
);

COMMENT ON TABLE cua_hang IS 'Cửa hàng';

CREATE TABLE tai_khoan_nhan_tien (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cua_hang_id int NOT NULL,
    ma_ngan_hang varchar(30) NOT NULL,
    so_tai_khoan varchar(50) NOT NULL,
    ten_nguoi_nhan varchar(150) NOT NULL,
    dang_su_dung bool NOT NULL,
    tao_luc timestamptz NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (id, cua_hang_id)
);

COMMENT ON TABLE tai_khoan_nhan_tien IS 'Tài khoản nhận tiền';

CREATE TABLE thong_bao (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nguoi_nhan_id int NOT NULL,
    don_hang_id int,
    cua_hang_id int,
    loai varchar(40) NOT NULL,
    noi_dung text NOT NULL,
    tao_luc timestamptz NOT NULL,
    gui_luc timestamptz,
    xac_nhan_nhan_luc timestamptz,
    bang_chung_nhan text,
    PRIMARY KEY (id),
    UNIQUE (id, don_hang_id, cua_hang_id),
    CHECK ((don_hang_id IS NULL) = (cua_hang_id IS NULL)),
    CHECK (xac_nhan_nhan_luc IS NULL OR bang_chung_nhan IS NOT NULL)
);

COMMENT ON TABLE thong_bao IS 'Thông báo';

CREATE TABLE tep_tin (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nguoi_tai_id int NOT NULL,
    khoa_luu_tru text NOT NULL,
    ten_tep varchar(255) NOT NULL,
    mime_type varchar(100) NOT NULL,
    kich_thuoc bigint NOT NULL,
    sha256 char(64) NOT NULL,
    tao_luc timestamptz NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (khoa_luu_tru),
    CHECK (kich_thuoc >= 0)
);

COMMENT ON TABLE tep_tin IS 'Tệp tin';

CREATE TABLE nhom_thuc_pham (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ma varchar(40) NOT NULL,
    ten varchar(120) NOT NULL,
    dang_su_dung bool NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (ma)
);

COMMENT ON TABLE nhom_thuc_pham IS 'Nhóm thực phẩm';

CREATE TABLE mon_an (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cua_hang_id int NOT NULL,
    nhom_id int NOT NULL,
    ten varchar(160) NOT NULL,
    thanh_phan text NOT NULL,
    canh_bao text NOT NULL,
    gia_niem_yet numeric(18,0) NOT NULL,
    dang_su_dung bool NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (id, cua_hang_id),
    CHECK (gia_niem_yet >= 0)
);

COMMENT ON TABLE mon_an IS 'Món ăn';

CREATE TABLE mau_hop (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cua_hang_id int NOT NULL,
    nhom_id int NOT NULL,
    ten varchar(160) NOT NULL,
    mo_ta text NOT NULL,
    canh_bao text NOT NULL,
    anh_id int,
    dang_su_dung bool NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (id, cua_hang_id)
);

COMMENT ON TABLE mau_hop IS 'Mẫu hộp';

CREATE TABLE chinh_sach_tai_chinh (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    so_phien_ban int NOT NULL,
    ty_le_coc numeric(7,6) NOT NULL,
    ty_le_hoa_hong numeric(7,6) NOT NULL,
    quy_tac_huy text NOT NULL,
    hieu_luc_tu timestamptz NOT NULL,
    nguoi_tao_id int NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (so_phien_ban),
    CHECK (ty_le_coc > 0 AND ty_le_coc <= 1),
    CHECK (ty_le_hoa_hong >= 0 AND ty_le_hoa_hong <= 1)
);

COMMENT ON TABLE chinh_sach_tai_chinh IS 'Chính sách tài chính';

CREATE TABLE xac_minh_no_show (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    don_hang_id int NOT NULL,
    cua_hang_id int NOT NULL,
    nguoi_xac_minh_id int,
    ket_qua varchar(24) NOT NULL,
    xac_minh_luc timestamptz,
    thong_bao_id int,
    tien_coc_giu_lai numeric(18,0) NOT NULL,
    trang_thai_bu_dap varchar(24) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (don_hang_id),
    UNIQUE (id, don_hang_id, cua_hang_id),
    CHECK (tien_coc_giu_lai >= 0),
    CHECK (ket_qua IN ('CHO_XAC_MINH','KHACH_KHONG_DEN','LOI_CUA_HANG','CHUA_DU_CAN_CU')),
    CHECK (trang_thai_bu_dap IN ('KHONG_AP_DUNG','DANG_GIU','DU_DIEU_KIEN','DA_GHI_NHAN')),
    CHECK (ket_qua <> 'KHACH_KHONG_DEN' OR (nguoi_xac_minh_id IS NOT NULL AND xac_minh_luc IS NOT NULL))
);

COMMENT ON TABLE xac_minh_no_show IS 'Hồ sơ không nhận hàng';

CREATE TABLE tep_dinh_kem (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tep_id int NOT NULL,
    ho_so_id int,
    mon_an_id int,
    khieu_nai_id int,
    no_show_id int,
    thanh_toan_id int,
    hoan_tien_id int,
    chi_tra_id int,
    PRIMARY KEY (id),
    CHECK (num_nonnulls(ho_so_id,mon_an_id,khieu_nai_id,no_show_id,thanh_toan_id,hoan_tien_id,chi_tra_id) = 1)
);

COMMENT ON TABLE tep_dinh_kem IS 'Tệp đính kèm';

CREATE TABLE lich_su_gia (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    mon_an_id int NOT NULL,
    cua_hang_id int NOT NULL,
    gia_cu numeric(18,0) NOT NULL,
    gia_moi numeric(18,0) NOT NULL,
    nguoi_sua_id int NOT NULL,
    doi_luc timestamptz NOT NULL,
    ly_do text,
    PRIMARY KEY (id),
    CHECK (gia_cu >= 0),
    CHECK (gia_moi >= 0)
);

COMMENT ON TABLE lich_su_gia IS 'Lịch sử giá';

CREATE TABLE thanh_phan_hop (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    hop_id int NOT NULL,
    mon_an_id int NOT NULL,
    cua_hang_id int NOT NULL,
    so_luong int NOT NULL,
    ten_mon_da_chot varchar(160) NOT NULL,
    don_gia_da_chot numeric(18,0) NOT NULL,
    canh_bao_da_chot text NOT NULL,
    han_su_dung timestamptz NOT NULL,
    bao_quan text NOT NULL,
    PRIMARY KEY (id),
    CHECK (so_luong > 0),
    CHECK (don_gia_da_chot >= 0)
);

COMMENT ON TABLE thanh_phan_hop IS 'Thành phần hộp';

CREATE TABLE hop_thuc_te (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cua_hang_id int NOT NULL,
    dot_ban_id int NOT NULL,
    ma_hop varchar(40) NOT NULL,
    nguoi_dong_goi_id int NOT NULL,
    dong_goi_luc timestamptz NOT NULL,
    an_toan_den timestamptz NOT NULL,
    trang_thai varchar(24) NOT NULL,
    ly_do_loai text,
    PRIMARY KEY (id),
    UNIQUE (ma_hop),
    UNIQUE (id, cua_hang_id),
    UNIQUE (id, dot_ban_id, cua_hang_id),
    CHECK (an_toan_den > dong_goi_luc),
    CHECK (trang_thai IN ('DA_DONG_GOI','KHONG_DAT','DA_BAN_GIAO'))
);

COMMENT ON TABLE hop_thuc_te IS 'Hộp thực tế';

CREATE TABLE dot_ban (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cua_hang_id int NOT NULL,
    mau_hop_id int NOT NULL,
    gia_ban numeric(18,0) NOT NULL,
    gia_tri_cam_ket numeric(18,0) NOT NULL,
    han_dat_hang timestamptz NOT NULL,
    bat_dau_nhan timestamptz NOT NULL,
    ket_thuc_nhan timestamptz NOT NULL,
    trang_thai varchar(24) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (id, cua_hang_id),
    CHECK (gia_ban > 0),
    CHECK (gia_tri_cam_ket > 0),
    CHECK (han_dat_hang <= ket_thuc_nhan),
    CHECK (bat_dau_nhan < ket_thuc_nhan),
    CHECK (trang_thai IN ('NHAP','DANG_BAN','TAM_DUNG','DA_DONG'))
);

COMMENT ON TABLE dot_ban IS 'Đợt bán';

CREATE TABLE don_hang (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ma_don varchar(40) NOT NULL,
    khach_hang_id int NOT NULL,
    cua_hang_id int NOT NULL,
    dot_ban_id int NOT NULL,
    chinh_sach_id int NOT NULL,
    so_luong int NOT NULL,
    don_gia_da_chot numeric(18,0) NOT NULL,
    gia_tri_cam_ket_moi_hop numeric(18,0) NOT NULL,
    ty_le_coc numeric(7,6) NOT NULL,
    ty_le_hoa_hong numeric(7,6) NOT NULL,
    hinh_thuc_thanh_toan varchar(16) NOT NULL,
    bat_dau_nhan timestamptz NOT NULL,
    ket_thuc_nhan timestamptz NOT NULL,
    canh_bao_da_thong_bao text NOT NULL,
    ma_nhan_hash varchar(128),
    tao_luc timestamptz NOT NULL,
    het_han_giu timestamptz NOT NULL,
    xac_nhan_luc timestamptz,
    hoan_tat_luc timestamptz,
    trang_thai varchar(32) NOT NULL,
    ly_do_huy text,
    PRIMARY KEY (id),
    UNIQUE (ma_don),
    UNIQUE (ma_nhan_hash),
    UNIQUE (id, cua_hang_id),
    UNIQUE (id, dot_ban_id, cua_hang_id),
    CHECK (so_luong > 0),
    CHECK (don_gia_da_chot > 0),
    CHECK (gia_tri_cam_ket_moi_hop > 0),
    CHECK (ty_le_coc > 0 AND ty_le_coc <= 1),
    CHECK (ty_le_hoa_hong >= 0 AND ty_le_hoa_hong <= 1),
    CHECK (bat_dau_nhan < ket_thuc_nhan),
    CHECK (het_han_giu > tao_luc),
    CHECK (hinh_thuc_thanh_toan IN ('TOAN_BO','DAT_COC')),
    CHECK (trang_thai IN ('CHO_THANH_TOAN','DA_XAC_NHAN','HET_HAN','DA_HUY','CHO_XAC_MINH_NO_SHOW','NO_SHOW','HOAN_TAT')),
    CHECK (trang_thai NOT IN ('DA_XAC_NHAN','CHO_XAC_MINH_NO_SHOW','NO_SHOW','HOAN_TAT') OR (xac_nhan_luc IS NOT NULL AND ma_nhan_hash IS NOT NULL)),
    CHECK (trang_thai <> 'HOAN_TAT' OR hoan_tat_luc IS NOT NULL)
);

COMMENT ON TABLE don_hang IS 'Đơn hàng';

CREATE TABLE khieu_nai (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nguoi_gui_id int NOT NULL,
    cua_hang_id int NOT NULL,
    don_hang_id int,
    noi_dung text NOT NULL,
    gui_luc timestamptz NOT NULL,
    trang_thai varchar(24) NOT NULL,
    quyet_dinh text,
    nguoi_xu_ly_id int,
    quyet_dinh_luc timestamptz,
    PRIMARY KEY (id),
    UNIQUE (id, don_hang_id, cua_hang_id),
    CHECK (trang_thai IN ('MOI_GUI','DANG_XU_LY','DA_CO_QUYET_DINH','DA_DONG'))
);

COMMENT ON TABLE khieu_nai IS 'Khiếu nại';

CREATE TABLE phan_bo_hop (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    don_hang_id int NOT NULL,
    hop_id int NOT NULL,
    dot_ban_id int NOT NULL,
    cua_hang_id int NOT NULL,
    giu_luc timestamptz NOT NULL,
    het_han_giu timestamptz NOT NULL,
    trang_thai varchar(24) NOT NULL,
    ket_thuc_luc timestamptz,
    ly_do_giai_phong text,
    PRIMARY KEY (id),
    CHECK (het_han_giu > giu_luc),
    CHECK (trang_thai IN ('DANG_GIU','DA_XAC_NHAN','DA_GIAI_PHONG','DA_BAN_GIAO'))
);

COMMENT ON TABLE phan_bo_hop IS 'Phân bổ hộp';

CREATE TABLE thanh_toan (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    don_hang_id int NOT NULL,
    cua_hang_id int NOT NULL,
    noi_nhan varchar(20) NOT NULL,
    phuong_thuc varchar(24) NOT NULL,
    so_tien numeric(18,0) NOT NULL,
    nha_cung_cap varchar(60) NOT NULL,
    ma_tham_chieu varchar(150),
    ma_chong_trung varchar(150) NOT NULL,
    trang_thai varchar(24) NOT NULL,
    tao_luc timestamptz NOT NULL,
    xac_minh_luc timestamptz,
    nguoi_xac_nhan_id int,
    PRIMARY KEY (id),
    UNIQUE (ma_chong_trung),
    UNIQUE (nha_cung_cap, ma_tham_chieu),
    UNIQUE (id, don_hang_id, cua_hang_id),
    CHECK (so_tien > 0),
    CHECK ((noi_nhan = 'QUA_UNG_DUNG' AND phuong_thuc = 'CONG_THANH_TOAN') OR (noi_nhan = 'TAI_CUA_HANG' AND phuong_thuc IN ('TIEN_MAT','CHUYEN_KHOAN'))),
    CHECK (trang_thai IN ('CHO_XU_LY','DANG_XU_LY','CHO_XAC_MINH','THANH_CONG','THAT_BAI')),
    CHECK (trang_thai <> 'THANH_CONG' OR (xac_minh_luc IS NOT NULL AND ((noi_nhan = 'QUA_UNG_DUNG' AND ma_tham_chieu IS NOT NULL) OR (noi_nhan = 'TAI_CUA_HANG' AND nguoi_xac_nhan_id IS NOT NULL AND (phuong_thuc = 'TIEN_MAT' OR ma_tham_chieu IS NOT NULL)))))
);

COMMENT ON TABLE thanh_toan IS 'Thanh toán';

CREATE TABLE yeu_cau_hoan_tien (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    don_hang_id int NOT NULL,
    cua_hang_id int NOT NULL,
    khieu_nai_id int,
    ly_do text NOT NULL,
    so_tien_duoc_duyet numeric(18,0) NOT NULL,
    nguoi_duyet_id int,
    duyet_luc timestamptz NOT NULL,
    ma_chong_trung varchar(150) NOT NULL,
    trang_thai varchar(24) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (ma_chong_trung),
    UNIQUE (id, don_hang_id, cua_hang_id),
    CHECK (so_tien_duoc_duyet > 0),
    CHECK (trang_thai IN ('DA_DUYET','DANG_HOAN','DA_HOAN'))
);

COMMENT ON TABLE yeu_cau_hoan_tien IS 'Yêu cầu hoàn tiền';

CREATE TABLE hoan_tien (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    yeu_cau_id int NOT NULL,
    thanh_toan_goc_id int NOT NULL,
    don_hang_id int NOT NULL,
    cua_hang_id int NOT NULL,
    so_tien numeric(18,0) NOT NULL,
    ma_chong_trung varchar(150) NOT NULL,
    nha_cung_cap varchar(60) NOT NULL,
    ma_tham_chieu varchar(150),
    trang_thai varchar(24) NOT NULL,
    tao_luc timestamptz NOT NULL,
    hoan_thanh_luc timestamptz,
    PRIMARY KEY (id),
    UNIQUE (ma_chong_trung),
    UNIQUE (nha_cung_cap, ma_tham_chieu),
    UNIQUE (id, don_hang_id, cua_hang_id),
    CHECK (so_tien > 0),
    CHECK (trang_thai IN ('CHO_XU_LY','DANG_XU_LY','CHO_XAC_MINH','THANH_CONG','THAT_BAI')),
    CHECK (trang_thai <> 'THANH_CONG' OR hoan_thanh_luc IS NOT NULL)
);

COMMENT ON TABLE hoan_tien IS 'Hoàn tiền';

CREATE TABLE chi_tra (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    bang_doi_soat_id int NOT NULL,
    cua_hang_id int NOT NULL,
    tai_khoan_nhan_id int NOT NULL,
    so_tien numeric(18,0) NOT NULL,
    ngan_hang_da_chot varchar(30) NOT NULL,
    so_tai_khoan_da_chot varchar(50) NOT NULL,
    nguoi_nhan_da_chot varchar(150) NOT NULL,
    ma_chong_trung varchar(150) NOT NULL,
    ma_chuyen_tien varchar(150),
    trang_thai varchar(24) NOT NULL,
    tao_luc timestamptz NOT NULL,
    chuyen_luc timestamptz,
    nguoi_xac_nhan_id int,
    PRIMARY KEY (id),
    UNIQUE (ma_chong_trung),
    UNIQUE (ngan_hang_da_chot, ma_chuyen_tien),
    CHECK (so_tien > 0),
    CHECK (trang_thai IN ('CHO_CHUYEN','CHO_XAC_MINH','THANH_CONG','THAT_BAI')),
    CHECK (trang_thai <> 'THANH_CONG' OR (chuyen_luc IS NOT NULL AND ma_chuyen_tien IS NOT NULL AND nguoi_xac_nhan_id IS NOT NULL))
);

COMMENT ON TABLE chi_tra IS 'Chi trả cửa hàng';

CREATE TABLE bang_doi_soat (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cua_hang_id int NOT NULL,
    bang_truoc_id int,
    tu_ngay timestamptz NOT NULL,
    den_ngay timestamptz NOT NULL,
    so_du_dau_ky numeric(18,0) NOT NULL,
    so_du_ket_chuyen numeric(18,0),
    trang_thai varchar(24) NOT NULL,
    chot_luc timestamptz,
    ket_chuyen_luc timestamptz,
    PRIMARY KEY (id),
    UNIQUE (id, cua_hang_id),
    UNIQUE (bang_truoc_id),
    CHECK (tu_ngay < den_ngay),
    CHECK (bang_truoc_id IS NULL OR bang_truoc_id <> id),
    CHECK (trang_thai IN ('NHAP','DA_CHOT','DA_KET_CHUYEN')),
    CHECK ((trang_thai = 'DA_KET_CHUYEN') = (so_du_ket_chuyen IS NOT NULL AND ket_chuyen_luc IS NOT NULL)),
    CHECK (trang_thai = 'NHAP' OR chot_luc IS NOT NULL)
);

COMMENT ON TABLE bang_doi_soat IS 'Bảng đối soát';

CREATE TABLE dong_doi_soat (
    bang_id int NOT NULL,
    but_toan_id int NOT NULL,
    cua_hang_id int NOT NULL,
    so_thu_tu int NOT NULL,
    so_tien_da_chot numeric(18,0) NOT NULL,
    da_chot bool NOT NULL,
    PRIMARY KEY (bang_id, but_toan_id),
    UNIQUE (bang_id, so_thu_tu),
    CHECK (so_thu_tu > 0)
);

COMMENT ON TABLE dong_doi_soat IS 'Chi tiết đối soát';

CREATE TABLE but_toan (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    su_kien_id int NOT NULL,
    don_hang_id int NOT NULL,
    cua_hang_id int NOT NULL,
    but_toan_goc_id int,
    loai varchar(40) NOT NULL,
    so_tien_co_dau numeric(18,0) NOT NULL,
    ma_chong_trung varchar(150) NOT NULL,
    ghi_luc timestamptz NOT NULL,
    du_dieu_kien_tu timestamptz,
    dang_bi_giu bool NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (ma_chong_trung),
    UNIQUE (id, cua_hang_id),
    UNIQUE (id, don_hang_id, cua_hang_id),
    CHECK (so_tien_co_dau <> 0),
    CHECK (but_toan_goc_id IS NULL OR but_toan_goc_id <> id),
    CHECK (loai IN ('TIEN_BAN_HANG','HOA_HONG','TIEN_THU_TAI_CUA_HANG','BU_DAP_NO_SHOW','DIEU_CHINH'))
);

COMMENT ON TABLE but_toan IS 'Bút toán';

CREATE TABLE su_kien_tai_chinh (
    id int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    don_hang_id int NOT NULL,
    cua_hang_id int NOT NULL,
    loai varchar(32) NOT NULL,
    hoan_tien_id int,
    no_show_id int,
    khieu_nai_id int,
    ma_chong_trung varchar(150) NOT NULL,
    du_lieu_da_chot text NOT NULL,
    phat_sinh_luc timestamptz NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (ma_chong_trung),
    UNIQUE (id, don_hang_id, cua_hang_id),
    CHECK ((loai = 'HOAN_TAT_DON' AND num_nonnulls(hoan_tien_id,no_show_id,khieu_nai_id)=0) OR (loai = 'HOAN_TIEN' AND hoan_tien_id IS NOT NULL AND num_nonnulls(hoan_tien_id,no_show_id,khieu_nai_id)=1) OR (loai = 'NO_SHOW' AND no_show_id IS NOT NULL AND num_nonnulls(hoan_tien_id,no_show_id,khieu_nai_id)=1) OR (loai = 'QUYET_DINH_KHIEU_NAI' AND khieu_nai_id IS NOT NULL AND num_nonnulls(hoan_tien_id,no_show_id,khieu_nai_id)=1))
);

COMMENT ON TABLE su_kien_tai_chinh IS 'Sự kiện tài chính';

